export const foodById = (id: string): Food | undefined => FOODS.find((f) => f.id === id);
export function searchFoods(q: string, limit = 40): Food[] {
  const needle = q.trim().toLowerCase();
  if (!needle) return [];
  return FOODS.filter((f) => `${f.name} ${f.aliases}`.toLowerCase().includes(needle)).slice(0, limit);
}
